import assert from 'node:assert/strict';
import { SOURCE, TITLES, OBSERVATIONS, encode, frame, parseLog, project, validateSuccess } from './production-fixes-log-receipt.mjs';
const expected={source:SOURCE,tooling:'a'.repeat(40),run:'100',attempt:'1',producerJobId:'101',receiptJobId:'102'};
const service={...expected,workflowStatus:'completed',producerStatus:'completed',receiptStatus:'completed',sdkStatus:'completed',workflowConclusion:'success',producerConclusion:'success',receiptConclusion:'success',sdkConclusion:'success'};
function raw(){return{source:SOURCE,tooling:expected.tooling,run:'100',attempt:'1',command:{schema:1,exitCode:0},sdkStepOutcome:'success',report:{errors:[],stats:{expected:4,unexpected:0,skipped:0,flaky:0},suites:[{specs:Object.entries(TITLES).flatMap(([file,titles])=>titles.map(title=>({file,title,ok:true,tests:[{expectedStatus:'passed',status:'expected',results:[{status:'passed',retry:0,errors:[],attachments:[{name:'production-fix-observation',contentType:'application/json',body:Buffer.from(JSON.stringify(OBSERVATIONS[title])).toString('base64')}]}]}]})))}]}};}
const result=r=>r.report.suites[0].specs[0].tests[0].results[0];let checks=0;
function check(name,fn){fn();console.log('ok '+(++checks)+' - '+name);}
check('four cases and exact non-qualifying observations roundtrip',()=>{const p=parseLog(frame(encode(raw())));assert.equal(validateSuccess(p.receipt,expected,service).passed,4);});
check('global teardown error never hidden by empty case errors',()=>{const r=raw();r.report.errors.push({message:'synthetic teardown failure'});assert.throws(()=>validateSuccess(project(r),expected,service),/GLOBAL_ERROR/);});
check('nonzero SDK command fails even with passed tests',()=>{const r=raw();r.command.exitCode=1;assert.throws(()=>validateSuccess(project(r),expected,service),/SDK/);});
check('missing cancelled or failed SDK outcome cannot pass',()=>{for(const v of[undefined,'cancelled','failure']){const r=raw();r.sdkStepOutcome=v;assert.throws(()=>validateSuccess(project(r),expected,service),/SDK/);}});
check('failed skipped retried or erroneous case cannot pass',()=>{for(const p of[{status:'failed'},{status:'skipped'},{retry:1},{errors:[{message:'synthetic assertion'}]}]){const r=raw();Object.assign(result(r),p);assert.throws(()=>validateSuccess(project(r),expected,service),/CASE_FAILURE/);}});
check('missing or duplicate selected case cannot pass',()=>{for(const duplicate of[false,true]){const r=raw();r.report.suites[0].specs.pop();if(duplicate)r.report.suites[0].specs.push(structuredClone(r.report.suites[0].specs[0]));assert.throws(()=>validateSuccess(project(r),expected,service),/SPEC_COUNT|SELECTED/);}});
check('legacy screenshot Gateway and deletion selection fails',()=>{for(const file of['automation.spec.ts','ssh-console-gateway.spec.ts','stored-console-results.spec.ts','reset.spec.ts']){const r=raw();r.report.suites[0].specs[0].file=file;assert.throws(()=>validateSuccess(project(r),expected,service),/SELECTED/);}});
check('missing or changed observation cannot pass',()=>{for(const omit of[true,false]){const r=raw();if(omit)result(r).attachments=[];else result(r).attachments[0].body=Buffer.from('{}').toString('base64');assert.throws(()=>validateSuccess(project(r),expected,service),/OBSERVATION/);}});
check('false source or cleanup claim cannot pass',()=>{for(const [file,titles]of Object.entries(TITLES))for(const title of titles){const r=raw(),s=r.report.suites[0].specs.find(x=>x.file===file&&x.title===title),o=structuredClone(OBSERVATIONS[title]);o.productionSource='b'.repeat(40);s.tests[0].results[0].attachments[0].body=Buffer.from(JSON.stringify(o)).toString('base64');assert.throws(()=>validateSuccess(project(r),expected,service),/OBSERVATION_MISMATCH/);}});
check('independent service run job and outcome must match',()=>{for(const p of[{run:'200'},{producerJobId:'201'},{receiptJobId:'202'},{producerConclusion:'cancelled'}])assert.throws(()=>validateSuccess(project(raw()),expected,{...service,...p}),/SERVICE_/);});
check('identity and attempt required',()=>{const r=raw();r.source='b'.repeat(40);assert.throws(()=>project(r),/IDENTITY/);assert.throws(()=>validateSuccess(project(raw()),{...expected,receiptJobId:undefined},service),/EXPECTED/);});
check('bounds reject raw projection observation and log overflow',()=>{let r=raw();r.padding='x'.repeat(1048576);assert.throws(()=>project(r),/RAW_CAP/);r=raw();result(r).attachments[0].body=Buffer.alloc(4097).toString('base64');assert.throws(()=>project(r),/ATTACHMENT_CAP/);r=raw();r.report.errors=[{message:'x'.repeat(32769)}];assert.throws(()=>project(r),/PROJECTION_CAP/);assert.throws(()=>parseLog('x'.repeat(1048577)),/LOG_CAP/);});
check('bad duplicate missing or changed frame fails',()=>{const f=frame(encode(raw()));assert.throws(()=>parseLog(f+'\n'+f),/FRAME_COUNT/);assert.throws(()=>parseLog('none'),/FRAME_COUNT/);assert.throws(()=>parseLog(f.replace(/ [a-f0-9]{64} /,' '+'f'.repeat(64)+' ')),/FRAME_INTEGRITY/);});
check('original failure facts preserved with SDK failure-context metadata only',()=>{const r=raw(),v=result(r);r.command.exitCode=1;r.sdkStepOutcome='failure';v.status='failed';v.error={message:'synthetic original failure'};v.errors=[v.error];v.attachments.push({name:'error-context',contentType:'text/markdown',path:'/synthetic/private-context.md'});const p=project(r);assert.deepEqual(result(p).errors,v.errors);assert.deepEqual(result(p).error,v.error);assert.equal(result(p).attachments.at(-1).bodyOmitted,true);assert(!JSON.stringify(p).includes('/synthetic/private-context.md'));assert.throws(()=>validateSuccess(p,expected,service),/SDK/);});
check('SDK context never qualifies success and bad stats fail',()=>{const r=raw();result(r).attachments.push({name:'error-context',contentType:'text/markdown',path:'/synthetic/context.md'});assert.throws(()=>validateSuccess(project(r),expected,service),/OBSERVATION/);r.report.stats.skipped=1;assert.throws(()=>validateSuccess(project(r),expected,service),/STATS/);});
console.log(JSON.stringify({checks,selectedCases:4,pureMemoryOnly:true}));
